-- Task Dungeon ZonePoints
--
-- Restores the 110 ZonePoint rows that route a player with an active
-- TaskDungeonMission into their personal/group TaskDungeonInstance, plus
-- the per-realm task-hub portals (rows with Id 415-419, 600-608, 625, 428)
-- and the dungeon-exit rows.
--
-- The TaskDungeonJumpPoint handler lives in
-- GameServer/serverrules/TaskDungeonJumpPoint.cs
-- (namespace DOL.GS.ServerRules.TaskDungeonJumpPoint).
--
-- Bug fixed vs the upstream DOLSharp dump: many original rows used
-- 'DOL.GS.Scripts.TaskDungeonJumpPoint' (wrong namespace), so those
-- rows silently failed to load the handler and the player got
-- "You need to have a proper mission before entering this area!" even
-- with a valid mission. All occurrences are normalised here.
--
-- Apply on the server:
--   docker exec -i opendaoc-db mariadb -uroot -p<root_pwd> opendaoc \
--     < sql/task_dungeon_zonepoints.sql
--
-- INSERT IGNORE is safe to re-apply: if a (Id, Realm) row already
-- exists it is left untouched; only missing rows are inserted.

SET FOREIGN_KEY_CHECKS=0;


SET FOREIGN_KEY_CHECKS=1;
